#!/usr/bin/env python3
import argparse
import csv
import hashlib
import io
import json
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path

TOKEN_PREFIX = 'TOKEN::'
LABEL_PREFIX = 'LABEL::'
TOKEN_RE = re.compile(r"[a-z0-9']+")
MAX_TOKENS_PER_REVIEW = 30
PRIOR_WEIGHT = 1e-9


def parse_args():
    p = argparse.ArgumentParser()
    p.add_argument('--dataset', required=True)
    p.add_argument('--output-dir', required=True)
    p.add_argument('--limit', type=int, default=None)
    p.add_argument('--repo-root', required=True)
    p.add_argument('--seed', type=int, default=0)
    return p.parse_args()


def read_jsonl_text(text):
    rows = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        if isinstance(obj, dict):
            rows.append(obj)
    return rows


def read_csv_text(text):
    rows = []
    reader = csv.DictReader(io.StringIO(text))
    if not reader.fieldnames:
        return rows
    field_map = {name.strip().lower(): name for name in reader.fieldnames if name}
    input_key = field_map.get('review')
    target_key = field_map.get('label')
    if input_key is None or target_key is None:
        return rows
    for rec in reader:
        rows.append({'review': rec.get(input_key, ''), 'label': rec.get(target_key, '')})
    return rows


def parse_dataset_bytes(raw, suffix, limit):
    text = raw.decode('utf-8-sig')
    if suffix == '.csv':
        rows = read_csv_text(text)
    else:
        rows = read_jsonl_text(text)
    if limit is not None:
        rows = rows[:max(0, limit)]
    return rows


def load_rows_from_path(path, limit):
    suffix = path.suffix.lower()
    raw = path.read_bytes()
    return parse_dataset_bytes(raw, suffix, limit)


def has_label(row, target_col):
    return target_col in row and row[target_col] is not None and str(row[target_col]).strip() != ''


def tokenize(text):
    seen = []
    for m in TOKEN_RE.finditer(str(text).lower()):
        tok = m.group(0)
        if len(tok) < 2:
            continue
        if tok not in seen:
            seen.append(tok)
        if len(seen) >= MAX_TOKENS_PER_REVIEW:
            break
    return seen


def token_item(tok):
    return TOKEN_PREFIX + tok


def label_item(label):
    return LABEL_PREFIX + str(label)


def mine_transactions(transactions, run_apriori):
    n = len(transactions)
    if n == 0:
        return [], []
    if n <= 1:
        min_support = 1.0
    elif n < 5:
        min_support = max(1.0 / n, 0.05)
    else:
        min_support = max(2.0 / n, 0.05)
    min_support = min(min_support, 1.0)
    return run_apriori(transactions, min_support, 0.01)


def extract_label_rules(rules):
    out = []
    for (ante, cons), conf in rules:
        if len(cons) != 1:
            continue
        c = cons[0]
        if not c.startswith(LABEL_PREFIX):
            continue
        label = c[len(LABEL_PREFIX):]
        ant = frozenset(ante)
        if ant and all(a.startswith(TOKEN_PREFIX) for a in ant):
            out.append((ant, label, float(conf)))
    return out


def predict(tokens, label_rules, label_counts):
    test_items = frozenset(token_item(t) for t in tokens)
    scores = defaultdict(float)
    total = sum(label_counts.values())
    if total:
        for label, count in label_counts.items():
            scores[label] += PRIOR_WEIGHT * (float(count) / float(total))
    for ant, label, conf in label_rules:
        if ant <= test_items:
            scores[label] += conf * (1.0 + 0.1 * len(ant))
    if not scores:
        return None
    return max(scores.items(), key=lambda kv: (kv[1], kv[0]))[0]


def compute_metrics(y_true, y_pred):
    n = len(y_true)
    if n == 0:
        return {}
    correct = sum(1 for a, b in zip(y_true, y_pred) if a == b)
    accuracy = correct / n
    labels = sorted(set(y_true))
    f1s = []
    for lab in labels:
        tp = sum(1 for t, p in zip(y_true, y_pred) if t == lab and p == lab)
        fp = sum(1 for t, p in zip(y_true, y_pred) if t != lab and p == lab)
        fn = sum(1 for t, p in zip(y_true, y_pred) if t == lab and p != lab)
        precision = tp / (tp + fp) if (tp + fp) else 0.0
        recall = tp / (tp + fn) if (tp + fn) else 0.0
        f1 = 2 * precision * recall / (precision + recall) if (precision + recall) else 0.0
        f1s.append(f1)
    return {'accuracy': float(accuracy), 'macro_f1': float(sum(f1s) / len(f1s)) if f1s else 0.0}


def write_json(path, obj):
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(obj, f, ensure_ascii=False, sort_keys=True)
        f.write(chr(10))


def write_predictions(path, preds):
    with open(path, 'w', encoding='utf-8') as f:
        for p in preds:
            f.write(json.dumps(p, ensure_ascii=False, sort_keys=True) + chr(10))


def load_auxiliary_training(repo_root, limit):
    candidates = [
        Path(repo_root) / '.research-assistant' / 'benchmark' / 'dataset' / 'validation.jsonl',
        Path(repo_root) / '.research-assistant' / 'uploads' / '01-reviews.csv',
    ]
    for path in candidates:
        if not path.is_file():
            continue
        try:
            rows = load_rows_from_path(path, limit)
        except Exception:
            continue
        labeled = [r for r in rows if has_label(r, 'label')]
        if labeled:
            return labeled
    return []


