    dataset_path = Path(args.dataset)
    output_dir = Path(args.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    raw = dataset_path.read_bytes()
    dataset_sha = hashlib.sha256(raw).hexdigest()
    rows = parse_dataset_bytes(raw, dataset_path.suffix.lower(), args.limit)

    sys.path.insert(0, str(Path(args.repo_root).resolve()))
    from apriori import runApriori

    input_col = 'review'
    target_col = 'label'
    all_tokens = [tokenize(r.get(input_col, '')) for r in rows]
    labeled_indices = [i for i, r in enumerate(rows) if has_label(r, target_col)]
    predictions = []
    metrics = {}
    status = 'ready'

    if labeled_indices:
        label_lookup = {str(rows[i][target_col]): rows[i][target_col] for i in labeled_indices}
        loo_pred = {}
        for i in labeled_indices:
            train_idx = [j for j in labeled_indices if j != i]
            if not train_idx:
                continue
            train_trans = []
            for j in train_idx:
                items = [token_item(t) for t in all_tokens[j]]
                items.append(label_item(rows[j][target_col]))
                train_trans.append(frozenset(items))
            _, rules = mine_transactions(train_trans, runApriori)
            label_rules = extract_label_rules(rules)
            label_counts = Counter(str(rows[j][target_col]) for j in train_idx)
            pred_str = predict(all_tokens[i], label_rules, label_counts)
            if pred_str is not None:
                loo_pred[i] = label_lookup.get(pred_str, pred_str)

        labeled_set = set(labeled_indices)
        unlabeled_indices = [i for i in range(len(rows)) if i not in labeled_set]
        full_pred = {}
        if unlabeled_indices:
            train_trans = []
            for j in labeled_indices:
                items = [token_item(t) for t in all_tokens[j]]
                items.append(label_item(rows[j][target_col]))
                train_trans.append(frozenset(items))
            _, rules = mine_transactions(train_trans, runApriori)
            label_rules = extract_label_rules(rules)
            label_counts = Counter(str(rows[j][target_col]) for j in labeled_indices)
            for i in unlabeled_indices:
                pred_str = predict(all_tokens[i], label_rules, label_counts)
                if pred_str is not None:
                    full_pred[i] = label_lookup.get(pred_str, pred_str)

        y_true = []
        y_pred = []
        for i, row in enumerate(rows):
            if i in loo_pred:
                pred = loo_pred[i]
                obj = {}
                if '__benchmark_id' in row:
                    obj['id'] = row['__benchmark_id']
                obj['prediction'] = pred
                obj['target'] = row[target_col]
                predictions.append(obj)
                y_true.append(row[target_col])
                y_pred.append(pred)
            elif i in full_pred:
                pred = full_pred[i]
                obj = {}
                if '__benchmark_id' in row:
                    obj['id'] = row['__benchmark_id']
                obj['prediction'] = pred
                predictions.append(obj)
        if y_true:
            metrics = compute_metrics(y_true, y_pred)
    else:
        train_rows = load_auxiliary_training(Path(args.repo_root), args.limit)
        if not train_rows:
            status = 'unsupported'
        else:
            train_tokens = [tokenize(r.get(input_col, '')) for r in train_rows]
            train_trans = []
            label_counts = Counter()
            label_lookup = {}
            for r, toks in zip(train_rows, train_tokens):
                items = [token_item(t) for t in toks]
                items.append(label_item(r[target_col]))
                train_trans.append(frozenset(items))
                lab = str(r[target_col])
                label_counts[lab] += 1
                label_lookup[lab] = r[target_col]
            _, rules = mine_transactions(train_trans, runApriori)
            label_rules = extract_label_rules(rules)
            for i, row in enumerate(rows):
                pred_str = predict(all_tokens[i], label_rules, label_counts)
                if pred_str is None:
                    continue
                obj = {}
                if '__benchmark_id' in row:
                    obj['id'] = row['__benchmark_id']
                obj['prediction'] = label_lookup.get(pred_str, pred_str)
                predictions.append(obj)

    if not predictions:
        status = 'unsupported'
    sample_count = len(predictions)
    write_json(output_dir / 'metrics.json', metrics)
    write_predictions(output_dir / 'predictions.jsonl', predictions)
    manifest = {
        'status': status,
        'dataset_sha256': dataset_sha,
        'sample_count': sample_count,
        'seed': args.seed,
        'adapter': 'apriori_associative_classifier',
    }
    write_json(output_dir / 'run_manifest.json', manifest)
    print(json.dumps({
        'status': status,
        'sample_count': sample_count,
        'metrics': metrics,
        'dataset_sha256': dataset_sha,
    }, ensure_ascii=False, sort_keys=True))


if __name__ == '__main__':
    main()

